package org.apache.commons.codec.binary;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen0Test {

    @Test
    public void testRead_NullBuffer() {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            try {
                bis.read(null, 0, 0);
                org.junit.Assert.fail("Expected NullPointerException");
            } catch (NullPointerException e) {
                // Success
            }
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_NegativeOffset() {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            try {
                bis.read(new byte[10], -1, 5);
                org.junit.Assert.fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_NegativeLen() {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            try {
                bis.read(new byte[10], 0, -1);
                org.junit.Assert.fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_OffsetOutOfBounds() {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            try {
                bis.read(new byte[10], 11, 0);
                org.junit.Assert.fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_OffsetPlusLenOutOfBounds() {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            try {
                bis.read(new byte[10], 5, 6);
                org.junit.Assert.fail("Expected IndexOutOfBoundsException");
            } catch (IndexOutOfBoundsException e) {
                // Success
            }
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }

    @Test
    public void testRead_LenZero() throws IOException {
        try (Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(new byte[0]))) {
            int result = bis.read(new byte[10], 0, 0);
            assertEquals(0, result);
        }
    }

    @Test
    public void testRead_Decode_WithOptimization() throws IOException {
        // Base64 for "abc" is "YWJj"
        byte[] inputData = "YWJj".getBytes();
        InputStream is = new ByteArrayInputStream(inputData);
        try (Base64InputStream bis = new Base64InputStream(is, false)) {
            byte[] b = new byte[3]; // len == b.length for optimization path
            int result = bis.read(b, 0, 3);
            assertEquals(3, result);
            assertEquals('a', (char) b[0]);
            assertEquals('b', (char) b[1]);
            assertEquals('c', (char) b[2]);
        }
    }

    @Test
    public void testRead_Encode_WithOptimization() throws IOException {
        // "abc" encoded is "YWJj"
        byte[] inputData = "abc".getBytes();
        InputStream is = new ByteArrayInputStream(inputData);
        try (Base64InputStream bis = new Base64InputStream(is, true)) {
            byte[] b = new byte[4]; // len == b.length for optimization path
            int result = bis.read(b, 0, 4);
            assertEquals(4, result);
            assertEquals('Y', (char) b[0]);
            assertEquals('W', (char) b[1]);
            assertEquals('J', (char) b[2]);
            assertEquals('j', (char) b[3]);
        }
    }

    @Test
    public void testRead_Decode_NoOptimization() throws IOException {
        byte[] inputData = "YWJj".getBytes();
        InputStream is = new ByteArrayInputStream(inputData);
        try (Base64InputStream bis = new Base64InputStream(is, false)) {
            byte[] b = new byte[10]; 
            // len (3) != b.length (10), triggers non-optimization path
            int result = bis.read(b, 0, 3);
            assertEquals(3, result);
            assertEquals('a', (char) b[0]);
        }
    }

    @Test
    public void testRead_EndOfStream() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (Base64InputStream bis = new Base64InputStream(is)) {
            byte[] b = new byte[10];
            int result = bis.read(b, 0, 10);
            // Depending on implementation, might return 0 or -1 once data is exhausted
            // but the logic should handle the read(buf) returning -1 safely
            if (result != -1) {
                org.junit.Assert.assertTrue(result >= 0);
            }
        }
    }
}
